const listAlbumSummaries = `-- name: ListAlbumSummaries :many
SELECT al.id, al.revision, al.artist_id, ar.name AS artist_name, ar.folder_key AS artist_key,
       al.title, al.folder_key AS title_key, al.year, al.genre, al.compilation,
       (al.deleted_at IS NOT NULL)::boolean AS trashed,
       al.cover_hash, cb.size AS cover_size, cb.format AS cover_format,
       al.published_path, al.published_revision, al.published_renderer,
       j.state AS job_state, j.error_code AS job_error_code, j.error_message AS job_error_message
FROM albums al
JOIN artists ar ON ar.id = al.artist_id
LEFT JOIN blobs cb ON cb.hash = al.cover_hash
LEFT JOIN jobs j ON j.kind = 'render' AND j.album_id = al.id
WHERE (CASE WHEN $1::boolean THEN j.state IS NOT DISTINCT FROM 'failed'
            ELSE (al.deleted_at IS NOT NULL) = $2::boolean END)
  AND (NOT $3::boolean OR al.artist_id = $4::uuid)
  AND ($5::boolean
       OR (ar.folder_key COLLATE "C", al.folder_key COLLATE "C", al.id)
          > ($6::text, $7::text, $8::uuid))
ORDER BY ar.folder_key COLLATE "C", al.folder_key COLLATE "C", al.id
LIMIT $9::int
`

type ListAlbumSummariesParams struct {
	Failed      bool
	Trashed     bool
	ByArtist    bool
	ArtistID    uuid.UUID
	First       bool
	AfterArtist string
	AfterTitle  string
	AfterID     uuid.UUID
	Lim         int32
}

type ListAlbumSummariesRow struct {
	ID                uuid.UUID
	Revision          int64
	ArtistID          uuid.UUID
	ArtistName        string
	ArtistKey         string
	Title             string
	TitleKey          string
	Year              *int32
	Genre             *string
	Compilation       bool
	Trashed           bool
	CoverHash         *string
	CoverSize         *int64
	CoverFormat       *string
	PublishedPath     *string
	PublishedRevision int64
	PublishedRenderer *string
	JobState          *string
	JobErrorCode      *string
	JobErrorMessage   *string
}

// §10.2 GET /api/albums: album summaries in the library's order, the
// artist's folder key, then the album's, then the id, byte-wise (COLLATE
// "C"). Keyset pagination: the page starts after the cursor's triple
// (NOTES.md N-190). The text search is applied by the caller with the
// normalization of internal/names, never with SQL lower() (§5.2). With
// @failed the page keeps only the albums whose render job failed (§10.3
// "Errore"), active or trashed, and @trashed is ignored (NOTES.md N-245).
func (q *Queries) ListAlbumSummaries(ctx context.Context, arg ListAlbumSummariesParams) ([]ListAlbumSummariesRow, error) {
	rows, err := q.db.Query(ctx, listAlbumSummaries,
		arg.Failed,
		arg.Trashed,
		arg.ByArtist,
		arg.ArtistID,
		arg.First,
		arg.AfterArtist,
		arg.AfterTitle,
		arg.AfterID,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListAlbumSummariesRow
	for rows.Next() {
		var i ListAlbumSummariesRow
		if err := rows.Scan(
			&i.ID,
			&i.Revision,
			&i.ArtistID,
			&i.ArtistName,
			&i.ArtistKey,
			&i.Title,
			&i.TitleKey,
			&i.Year,
			&i.Genre,
			&i.Compilation,
			&i.Trashed,
			&i.CoverHash,
			&i.CoverSize,
			&i.CoverFormat,
			&i.PublishedPath,
			&i.PublishedRevision,
			&i.PublishedRenderer,
			&i.JobState,
			&i.JobErrorCode,
			&i.JobErrorMessage,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

